float lkArmS(int c, float s, vec2 p, vec2 Tp) {
  vec2 q = lookQs(c, s); vec4 C0 = F(uOCh + 3 * c); int v = int(C0.x) + int(q.x);
  vec4 A = F(uOV + v); vec4 B = F(uOV + v + 1);
  vec2 d = B.xy - A.xy; float l2 = dot(d, d);
  return l2 > 0.0 ? s + dot(p - Tp, d) * (B.z - A.z) / l2 : s;
}
vec4 lkCornerMix(int k, vec2 p) {
